5	import java.sql.Timestamp;
6	import java.time.Clock;
7	import java.time.Duration;
8	import java.time.Instant;
9	import java.util.List;
10	
11	import org.springframework.dao.DuplicateKeyException;
12	import org.springframework.jdbc.core.JdbcTemplate;
13	import org.springframework.jdbc.core.RowMapper;
14	import org.springframework.jdbc.support.GeneratedKeyHolder;
15	import org.springframework.jdbc.support.KeyHolder;
16	import org.springframework.stereotype.Service;
17	import org.springframework.transaction.PlatformTransactionManager;
18	import org.springframework.transaction.annotation.Transactional;
19	import org.springframework.transaction.support.TransactionTemplate;
20	
21	import com.example.starter.error.ApiException;
22	import com.example.starter.ground.GroundWireService;
23	import com.example.starter.interlock.InterlockResult;
24	import com.example.starter.interlock.InterlockService;
25	import com.example.starter.ticket.TicketDtos.ArchiveRequest;
26	import com.example.starter.ticket.TicketDtos.ConfirmStepRequest;
27	import com.example.starter.ticket.TicketDtos.ConfirmView;
28	import com.example.starter.ticket.TicketDtos.CreateTicketRequest;
29	import com.example.starter.ticket.TicketDtos.HitView;
30	import com.example.starter.ticket.TicketDtos.IssueRequest;
31	import com.example.starter.ticket.TicketDtos.ReviewRequest;
32	import com.example.starter.ticket.TicketDtos.StepSpec;
33	import com.example.starter.ticket.TicketDtos.StepView;
34	import com.example.starter.ticket.TicketDtos.TicketDetailView;
35	import com.example.starter.ticket.TicketDtos.TicketView;
36	
37	/**
38	 * 倒闸操作票核心服务：拟票→审核→预发→逐项执行→归档流转，
39	 * 双人确认、24 小时有效期、防误闭锁联动与归档终态。
40	 */
41	@Service
42	public class SwitchingOrderService {
43	
44	    /** 操作票自预发起的有效期：24 小时，恰满即作废。 */
45	    public static final Duration VALIDITY = Duration.ofHours(24);
46	
47	    private static final RowMapper<TicketRow> TICKET_MAPPER = (rs, rowNum) -> new TicketRow(
48	            rs.getLong("id"),
49	            rs.getString("request_id"),
50	            rs.getString("interval_id"),
51	            rs.getString("title"),
52	            rs.getString("status"),
53	            rs.getString("reviewer_id"),
54	            toInstant(rs.getTimestamp("issued_at")),
55	            toInstant(rs.getTimestamp("expires_at")),
56	            toInstant(rs.getTimestamp("created_at")),
57	            toInstant(rs.getTimestamp("updated_at")));
58	
59	    private static final RowMapper<StepRow> STEP_MAPPER = (rs, rowNum) -> new StepRow(
60	            rs.getLong("id"),
61	            rs.getInt("seq"),
62	            rs.getString("operation_type"),
63	            rs.getString("device_id"),
64	            rs.getString("expected_state"),
65	            rs.getString("status"),
66	            rs.getString("operator_id"),
67	            rs.getString("guardian_id"),
68	            toInstant(rs.getTimestamp("executed_at")),
69	            rs.getBoolean("verified"));
70	
71	    private final JdbcTemplate jdbc;
72	    private final Clock clock;
73	    private final InterlockService interlockService;
74	    private final GroundWireService groundWireService;
75	    private final TransactionTemplate requiresNewTx;
76	
77	    public SwitchingOrderService(JdbcTemplate jdbc, Clock businessClock, InterlockService interlockService,
78	                                 GroundWireService groundWireService, PlatformTransactionManager txManager) {
79	        this.jdbc = jdbc;
80	        this.clock = businessClock;
81	        this.interlockService = interlockService;
82	        this.groundWireService = groundWireService;
83	        this.requiresNewTx = new TransactionTemplate(txManager);
84	        this.requiresNewTx.setPropagationBehavior(
85	                org.springframework.transaction.TransactionDefinition.PROPAGATION_REQUIRES_NEW);
86	    }
87	
88	    /** 拟票：创建 DRAFT 操作票及步骤。 */
89	    @Transactional
90	    public TicketDetailView create(CreateTicketRequest req) {
91	        Instant now = Instant.now(clock);
92	        KeyHolder keyHolder = new GeneratedKeyHolder();
93	        jdbc.update(con -> {
94	            PreparedStatement ps = con.prepareStatement(
95	                    "INSERT INTO switching_ticket (request_id, interval_id, title, status, created_at, updated_at)"
96	                            + " VALUES (?, ?, ?, 'DRAFT', ?, ?)",
97	                    Statement.RETURN_GENERATED_KEYS);
98	            ps.setString(1, req.requestId());
99	            ps.setString(2, req.intervalId());
100	            ps.setString(3, req.title());
101	            ps.setTimestamp(4, Timestamp.from(now));
102	            ps.setTimestamp(5, Timestamp.from(now));
103	            return ps;
104	        }, keyHolder);
105	        long ticketId = keyHolder.getKey().longValue();
106	        int seq = 1;
107	        for (StepSpec step : req.steps()) {
108	            jdbc.update(
109	                    "INSERT INTO switching_step (ticket_id, seq, operation_type, device_id, expected_state, status)"
110	                            + " VALUES (?, ?, ?, ?, ?, 'PENDING')",
111	                    ticketId, seq++, step.operationType(), step.deviceId(), step.expectedState());
112	        }
113	        return detail(ticketId);
114	    }
115	
116	    /** 审核：DRAFT → REVIEWED。 */
117	    @Transactional
118	    public TicketDetailView review(long ticketId, ReviewRequest req) {
119	        TicketRow ticket = mustLoad(ticketId);
120	        if (!"DRAFT".equals(ticket.status())) {
121	            throw ApiException.conflict("TICKET_STATE", "仅拟票状态可审核，当前状态: " + ticket.status());
122	        }
123	        jdbc.update("UPDATE switching_ticket SET status = 'REVIEWED', reviewer_id = ?, updated_at = ? WHERE id = ?",
124	                req.reviewerId(), Timestamp.from(Instant.now(clock)), ticketId);
125	        return detail(ticketId);
126	    }
127	
128	    /** 预发：REVIEWED → ISSUED，占用间隔执行锁，登记 24 小时有效期（UTC）。 */
129	    @Transactional
130	    public TicketDetailView issue(long ticketId, IssueRequest req) {
131	        TicketRow ticket = mustLoad(ticketId);
132	        if (!"REVIEWED".equals(ticket.status())) {
133	            throw ApiException.conflict("TICKET_STATE", "仅已审核状态可预发，当前状态: " + ticket.status());
134	        }
135	        Instant now = Instant.now(clock);
136	        try {
137	            jdbc.update("INSERT INTO interval_execution_lock (interval_id, ticket_id, acquired_at) VALUES (?, ?, ?)",
138	                    ticket.intervalId(), ticketId, Timestamp.from(now));
139	        } catch (DuplicateKeyException e) {
140	            throw ApiException.conflict("CONCURRENT_TICKET",
141	                    "间隔 " + ticket.intervalId() + " 已存在执行中操作票");
142	        }
143	        jdbc.update("UPDATE switching_ticket SET status = 'ISSUED', issued_at = ?, expires_at = ?, updated_at = ?"
144	                        + " WHERE id = ?",
145	                Timestamp.from(now), Timestamp.from(now.plus(VALIDITY)), Timestamp.from(now), ticketId);
146	        return detail(ticketId);
147	    }
148	
149	    /** 步骤双人确认：校验有效期、步序、双人确认与防误闭锁后执行一步。 */
150	    @Transactional
151	    public ConfirmView confirm(long ticketId, int seq, ConfirmStepRequest req) {
152	        TicketRow ticket = mustLoad(ticketId);
153	        refreshExpiry(ticket, true);
154	        if (!"ISSUED".equals(ticket.status()) && !"EXECUTING".equals(ticket.status())) {
155	            throw ApiException.conflict("TICKET_STATE", "仅预发或执行中状态可执行步骤，当前状态: " + ticket.status());
156	        }
157	        if (req.operatorId().equals(req.guardianId())) {
158	            throw ApiException.badRequest("DOUBLE_CONFIRM_REQUIRED", "操作人与监护人必须为两人，单人操作不生效");
159	        }
160	        StepRow step = jdbc.query("SELECT * FROM switching_step WHERE ticket_id = ? AND seq = ?",
161	                        STEP_MAPPER, ticketId, seq)
162	                .stream().findFirst()
163	                .orElseThrow(() -> ApiException.notFound("STEP_NOT_FOUND", "步骤不存在: " + seq));
164	        if (!"PENDING".equals(step.status())) {
165	            throw ApiException.conflict("STEP_STATE", "步骤已执行，当前状态: " + step.status());
166	        }
167	        Integer nextSeq = jdbc.query(
168	                        "SELECT MIN(seq) FROM switching_step WHERE ticket_id = ? AND status = 'PENDING'",
169	                        (rs, rowNum) -> rs.getInt(1), ticketId)
170	                .stream().findFirst().orElse(null);
171	        if (nextSeq == null || nextSeq != seq) {
172	            throw ApiException.conflict("STEP_ORDER", "须逐项执行，当前应执行步序: " + nextSeq);
173	        }
174	        InterlockResult interlock = interlockService.evaluate(step.operationType(), step.deviceId());
175	        if (interlock.blocked()) {
176	            interlockService.recordHit(ticketId, seq, interlock.ruleCode(), interlock.detail());
177	            throw ApiException.conflict("INTERLOCK_BLOCKED",
178	                    interlock.detail() + " [" + interlock.ruleCode() + "]");
179	        }
180	        // 实物联锁（不信任拟票快照）：送电类步在同一事务内复查该间隔所有实物接地线均已拆除。
181	        if (isEnergizing(step.operationType())) {
182	            try {
183	                groundWireService.assertNoAppliedWireOnEnergize(ticket.intervalId());
184	            } catch (ApiException e) {
185	                interlockService.recordHit(ticketId, seq, "GROUNDED_ENERGIZE", e.getMessage());
186	                throw e;
187	            }
188	        }
189	        Instant now = Instant.now(clock);
190	        jdbc.update("UPDATE switching_step SET status = 'DONE', operator_id = ?, guardian_id = ?, executed_at = ?"
191	                        + " WHERE id = ? AND status = 'PENDING'",
192	                req.operatorId(), req.guardianId(), Timestamp.from(now), step.id());
193	        jdbc.update("UPDATE device_state SET state = ?, updated_at = ? WHERE device_id = ?",
194	                step.expectedState(), Timestamp.from(now), step.deviceId());
195	        jdbc.update("UPDATE switching_ticket SET status = 'EXECUTING', updated_at = ? WHERE id = ?",
196	                Timestamp.from(now), ticketId);
197	        return new ConfirmView(ticketId, seq, "DONE", "EXECUTING");
198	    }
199	
200	    /** 归档：终态。重复归档返回幂等成功；到期票先转作废再归档。 */
201	    @Transactional
202	    public TicketDetailView archive(long ticketId, ArchiveRequest req) {
203	        TicketRow ticket = mustLoad(ticketId);
204	        if ("ARCHIVED".equals(ticket.status())) {
205	            return detail(ticketId);
206	        }
207	        ticket = refreshExpiry(ticket, false);
208	        switch (ticket.status()) {
209	            case "ISSUED", "EXECUTING", "EXCEPTION", "EXPIRED" -> {
210	                // 归档要求本票借用实物全部归还（历史借用与解锁记录保留）；有挂接实物须先合法拆除并归还。
211	                groundWireService.assertAllLoansReturned(ticketId);
212	                jdbc.update("UPDATE switching_ticket SET status = 'ARCHIVED', updated_at = ? WHERE id = ?",
213	                        Timestamp.from(Instant.now(clock)), ticketId);
214	                releaseLock(ticket.intervalId(), ticketId);
215	            }
216	            default -> throw ApiException.conflict("TICKET_STATE", "当前状态不可归档: " + ticket.status());
217	        }
218	        return detail(ticketId);
219	    }
220	
221	    /** 查询操作票详情：票、步序轨迹与闭锁命中。 */
222	    @Transactional(readOnly = true)
223	    public TicketDetailView get(long ticketId) {
224	        mustLoad(ticketId);
225	        return detail(ticketId);
226	    }
227	
228	    /**
229	     * 遥信核对：活动票最近一条已执行未核对步骤与回报比对，
230	     * 一致则标记核对，不符则中止操作票转异常并释放间隔锁。
231	     *
232	     * @return VERIFIED 核对一致 / ABORTED 不符中止 / RECORDED 仅记录
233	     */
234	    @Transactional
235	    public String processTelemetry(long ticketId, String deviceId, String state) {
236	        TicketRow ticket = mustLoad(ticketId);
237	        ticket = refreshExpiry(ticket, false);
238	        if (!"ISSUED".equals(ticket.status()) && !"EXECUTING".equals(ticket.status())) {
239	            return "RECORDED";
240	        }
241	        StepRow step = jdbc.query(
242	                        "SELECT * FROM switching_step WHERE ticket_id = ? AND status = 'DONE' AND verified = FALSE"
243	                                + " ORDER BY seq DESC LIMIT 1",
244	                        STEP_MAPPER, ticketId)
245	                .stream().findFirst().orElse(null);
246	        if (step == null || !step.deviceId().equals(deviceId)) {
247	            return "RECORDED";
248	        }
249	        if (step.expectedState().equals(state)) {
250	            jdbc.update("UPDATE switching_step SET verified = TRUE WHERE id = ?", step.id());
251	            return "VERIFIED";
252	        }
253	        jdbc.update("UPDATE switching_ticket SET status = 'EXCEPTION', updated_at = ? WHERE id = ?",
254	                Timestamp.from(Instant.now(clock)), ticketId);
255	        releaseLock(ticket.intervalId(), ticketId);
256	        return "ABORTED";
257	    }
258	
259	    /** 查询间隔当前执行中操作票主键，无则返回 null。 */
260	    public Long activeTicketForInterval(String intervalId) {
261	        return jdbc.query("SELECT ticket_id FROM interval_execution_lock WHERE interval_id = ?",
262	                        (rs, rowNum) -> rs.getLong(1), intervalId)
263	                .stream().findFirst().orElse(null);
264	    }
265	
266	    /** 判断间隔是否存在已归档操作票（用于迟到遥信标记）。 */
267	    public boolean hasArchivedTicket(String intervalId) {
268	        Integer count = jdbc.queryForObject(
269	                "SELECT COUNT(*) FROM switching_ticket WHERE interval_id = ? AND status = 'ARCHIVED'",
270	                Integer.class, intervalId);
271	        return count != null && count > 0;
272	    }
273	
274	    /**
275	     * 有效期检查：预发或执行中的票恰满 24 小时（UTC）即作废并释放间隔锁，已执行步骤保留。
276	     *
