79	
80	    /**
81	     * 批量借用：绑定未归档且未作废的操作票及间隔，一次可借多条，任一不可用整批拒绝。
82	     * 并发竞争同一实物时条件更新失败，整批回滚不双占。
83	     */
84	    @Transactional
85	    public WireBatchResult borrow(long ticketId, BorrowWiresRequest req) {
86	        TicketRef ticket = mustLoadTicket(ticketId);
87	        if ("ARCHIVED".equals(ticket.status())) {
88	            throw ApiException.unprocessable("TICKET_ARCHIVED", "操作票已归档，不可再借用接地线");
89	        }
90	        if ("EXPIRED".equals(ticket.status())) {
91	            throw ApiException.unprocessable("TICKET_VOID", "操作票已作废，不可再借用接地线");
92	        }
93	        List<String> codes = normalizedCodes(req.wireCodes());
94	        // 先逐条校验：任一不存在、不可用或版本不符，整批拒绝（不产生部分占用）
95	        for (String code : codes) {
96	            WireRow wire = mustLoadWire(code);
97	            if (!"AVAILABLE".equals(wire.status()) || wire.occupiedByTicket() != null) {
98	                throw ApiException.unprocessable("WIRE_NOT_AVAILABLE",
99	                        "接地线 " + code + " 当前不可借用，状态: " + wire.status());
100	            }
101	            if (wire.version() != req.expectedVersion()) {
102	                throw ApiException.unprocessable("VERSION_MISMATCH",
103	                        "接地线 " + code + " 期望版本 " + req.expectedVersion() + " 与当前版本 " + wire.version() + " 不符");
104	            }
105	        }
106	        Instant now = Instant.now(clock);
107	        for (String code : codes) {
108	            int updated = jdbc.update(
109	                    "UPDATE ground_wire SET status = 'BORROWED', interval_id = ?, occupied_by_ticket = ?,"
110	                            + " version = version + 1, updated_at = ?"
111	                            + " WHERE code = ? AND status = 'AVAILABLE' AND occupied_by_ticket IS NULL AND version = ?",
112	                    ticket.intervalId(), ticketId, Timestamp.from(now), code, req.expectedVersion());
113	            if (updated == 0) {
114	                // 并发竞争：实物刚被其他票占用，整批拒绝回滚
115	                throw ApiException.unprocessable("WIRE_NOT_AVAILABLE",
116	                        "接地线 " + code + " 已被其他操作票占用，整批借用拒绝");
117	            }
118	            jdbc.update(
119	                    "INSERT INTO ground_wire_loan (request_id, ticket_id, interval_id, wire_code, status,"
120	                            + " borrowed_at, created_at) VALUES (?, ?, ?, ?, 'BORROWED', ?, ?)",
121	                    req.requestId(), ticketId, ticket.intervalId(), code,
122	                    Timestamp.from(req.occurredAt()), Timestamp.from(now));
123	        }
124	        return new WireBatchResult("BORROWED", (int) (req.expectedVersion() + 1), codes, req.occurredAt());
125	    }
126	
127	    /**
128	     * 批量归还：仓管核对编号，仅核销本票借出且已拆除待归还的实物；
129	     * 已挂接或非本票借用的实物一律拒绝，整批回滚。
130	     */
131	    @Transactional
132	    public WireBatchResult returnWires(long ticketId, ReturnWiresRequest req) {
133	        mustLoadTicket(ticketId);
134	        List<String> codes = normalizedCodes(req.wireCodes());
135	        for (String code : codes) {
136	            WireRow wire = mustLoadWire(code);
137	            if (wire.version() != req.expectedVersion()) {
138	                throw ApiException.unprocessable("VERSION_MISMATCH",
139	                        "接地线 " + code + " 期望版本 " + req.expectedVersion() + " 与当前版本 " + wire.version() + " 不符");
140	            }
141	            Long loanId = jdbc.query(
142	                            "SELECT id FROM ground_wire_loan WHERE ticket_id = ? AND wire_code = ? AND status = 'BORROWED'",
143	                            (rs, n) -> rs.getLong(1), ticketId, code)
144	                    .stream().findFirst().orElse(null);
145	            if (loanId == null) {
146	                throw ApiException.unprocessable("WIRE_NOT_BORROWED_BY_TICKET",
147	                        "接地线 " + code + " 非本票借用或已归还，仓管核对拒绝核销");
148	            }
149	            if (wire.occupiedByTicket() == null || wire.occupiedByTicket() != ticketId
150	                    || !"REMOVED_PENDING_RETURN".equals(wire.status())) {
151	                throw ApiException.unprocessable("WIRE_NOT_DETACHED",
152	                        "接地线 " + code + " 尚未拆除，仅已拆除实物可归还核销，当前状态: " + wire.status());
153	            }
154	        }
155	        Instant now = Instant.now(clock);
156	        for (String code : codes) {
157	            long loanId = jdbc.queryForObject(
158	                    "SELECT id FROM ground_wire_loan WHERE ticket_id = ? AND wire_code = ? AND status = 'BORROWED'",
159	                    Long.class, ticketId, code);
160	            int updated = jdbc.update(
161	                    "UPDATE ground_wire SET status = 'AVAILABLE', interval_id = NULL, occupied_by_ticket = NULL,"
162	                            + " version = version + 1, updated_at = ?"
163	                            + " WHERE code = ? AND status = 'REMOVED_PENDING_RETURN' AND occupied_by_ticket = ?"
164	                            + " AND version = ?",
165	                    Timestamp.from(now), code, ticketId, req.expectedVersion());
166	            if (updated == 0) {
167	                throw ApiException.unprocessable("WIRE_NOT_DETACHED",
168	                        "接地线 " + code + " 状态已变化，归还拒绝，整批回滚");
169	            }
170	            jdbc.update(
171	                    "UPDATE ground_wire_loan SET status = 'RETURNED', returned_at = ?, return_request_id = ?,"
172	                            + " keeper_id = ? WHERE id = ?",
173	                    Timestamp.from(req.occurredAt()), req.requestId(), req.keeperId(), loanId);
174	        }
175	        return new WireBatchResult("RETURNED", (int) (req.expectedVersion() + 1), codes, req.occurredAt());
176	    }
177	
178	    /**
179	     * 挂接：引用本票 APPLY_GROUND 步骤，操作人与监护人双人确认，
180	     * 条件更新成功后状态为已挂接，并只追加一条不可覆盖的操作证据。
181	     */
182	    @Transactional
183	    public WireStepResult attach(long ticketId, AttachWireRequest req) {
184	        TicketRef ticket = mustLoadTicket(ticketId);
185	        if (!"ISSUED".equals(ticket.status()) && !"EXECUTING".equals(ticket.status())) {
186	            throw ApiException.unprocessable("TICKET_NOT_EXECUTING",
187	                    "仅预发或执行中的操作票可挂接接地线，当前状态: " + ticket.status());
188	        }
189	        if (req.operatorId().equals(req.guardianId())) {
190	            throw ApiException.badRequest("DOUBLE_CONFIRM_REQUIRED", "挂接须操作人与监护人两名不同人员共同确认");
191	        }
192	        StepRef step = mustLoadStep(ticketId, req.stepSeq());
193	        if (!"APPLY_GROUND".equals(step.operationType())) {
194	            throw ApiException.unprocessable("STEP_TYPE_MISMATCH",
195	                    "挂接须引用本票挂接地线步骤(APPLY_GROUND)，步序 " + req.stepSeq() + " 类型: " + step.operationType());
196	        }
197	        WireRow wire = mustLoadWire(req.wireCode());
198	        if (wire.version() != req.expectedVersion()) {
199	            throw ApiException.unprocessable("VERSION_MISMATCH",
200	                    "接地线 " + wire.code() + " 期望版本 " + req.expectedVersion() + " 与当前版本 " + wire.version() + " 不符");
201	        }
202	        if (wire.occupiedByTicket() == null || wire.occupiedByTicket() != ticketId || !"BORROWED".equals(wire.status())) {
203	            throw ApiException.unprocessable("WIRE_NOT_BORROWED",
204	                    "接地线 " + wire.code() + " 须由本票借用且处于借出未挂状态，当前状态: " + wire.status());
205	        }
206	        // 与送电事务统一加锁顺序：先锁实物行，再复查间隔带电状态，消除“先送电后挂线”的并发交错。
207	        jdbc.queryForObject("SELECT status FROM ground_wire WHERE code = ? FOR UPDATE", String.class, wire.code());
208	        long closedBreakers = jdbc.queryForObject(
209	                "SELECT COUNT(*) FROM device_state WHERE interval_id = ? AND device_type = 'BREAKER' AND state = 'CLOSED'",
210	                Long.class, ticket.intervalId());
211	        if (closedBreakers > 0) {
212	            throw ApiException.unprocessable("LIVE_GROUND",
213	                    "带电挂接地线：间隔 " + ticket.intervalId() + " 开关仍在合位，实物挂接拒绝");
214	        }
215	        Instant now = Instant.now(clock);
216	        int updated = jdbc.update(
217	                "UPDATE ground_wire SET status = 'APPLIED', version = version + 1, updated_at = ?"
218	                        + " WHERE code = ? AND status = 'BORROWED' AND occupied_by_ticket = ? AND version = ?",
219	                Timestamp.from(now), wire.code(), ticketId, req.expectedVersion());
220	        if (updated == 0) {
221	            throw ApiException.unprocessable("WIRE_STATE_CHANGED",
222	                    "接地线 " + wire.code() + " 状态已变化，挂接拒绝");
223	        }
224	        insertEvidence(wire.code(), ticketId, req.stepSeq(), ACTION_APPLIED,
225	                req.operatorId(), req.guardianId(), req.occurredAt(), req.requestId(), now);
226	        return new WireStepResult(ACTION_APPLIED, wire.code(), req.stepSeq(), "APPLIED",
227	                (int) (req.expectedVersion() + 1), req.occurredAt());
228	    }
229	
230	    /**
231	     * 拆除：引用本票 REMOVE_GROUND 步骤，双人确认，只追加不可覆盖证据。
232	     * 票作废（EXPIRED）或异常（EXCEPTION）不影响合法拆除，仍须双人确认。
233	     */
234	    @Transactional
235	    public WireStepResult detach(long ticketId, DetachWireRequest req) {
236	        TicketRef ticket = mustLoadTicket(ticketId);
237	        if (!"ISSUED".equals(ticket.status()) && !"EXECUTING".equals(ticket.status())
238	                && !"EXPIRED".equals(ticket.status()) && !"EXCEPTION".equals(ticket.status())) {
239	            throw ApiException.unprocessable("TICKET_STATE",
240	                    "当前票状态不允许拆除接地线: " + ticket.status());
241	        }
242	        if (req.operatorId().equals(req.guardianId())) {
243	            throw ApiException.badRequest("DOUBLE_CONFIRM_REQUIRED", "拆除须操作人与监护人两名不同人员共同确认");
244	        }
245	        StepRef step = mustLoadStep(ticketId, req.stepSeq());
246	        if (!"REMOVE_GROUND".equals(step.operationType())) {
247	            throw ApiException.unprocessable("STEP_TYPE_MISMATCH",
248	                    "拆除须引用本票拆接地线步骤(REMOVE_GROUND)，步序 " + req.stepSeq() + " 类型: " + step.operationType());
249	        }
250	        WireRow wire = mustLoadWire(req.wireCode());
251	        if (wire.version() != req.expectedVersion()) {
252	            throw ApiException.unprocessable("VERSION_MISMATCH",
253	                    "接地线 " + wire.code() + " 期望版本 " + req.expectedVersion() + " 与当前版本 " + wire.version() + " 不符");
254	        }
255	        if (wire.occupiedByTicket() == null || wire.occupiedByTicket() != ticketId || !"APPLIED".equals(wire.status())) {
256	            throw ApiException.unprocessable("WIRE_NOT_APPLIED",
257	                    "接地线 " + wire.code() + " 须为本票已挂接实物方可拆除，当前状态: " + wire.status());
258	        }
259	        Instant now = Instant.now(clock);
260	        int updated = jdbc.update(
261	                "UPDATE ground_wire SET status = 'REMOVED_PENDING_RETURN', version = version + 1, updated_at = ?"
262	                        + " WHERE code = ? AND status = 'APPLIED' AND occupied_by_ticket = ? AND version = ?",
263	                Timestamp.from(now), wire.code(), ticketId, req.expectedVersion());
264	        if (updated == 0) {
265	            throw ApiException.unprocessable("WIRE_STATE_CHANGED",
266	                    "接地线 " + wire.code() + " 状态已变化，拆除拒绝");
267	        }
268	        insertEvidence(wire.code(), ticketId, req.stepSeq(), ACTION_REMOVED,
269	                req.operatorId(), req.guardianId(), req.occurredAt(), req.requestId(), now);
270	        return new WireStepResult(ACTION_REMOVED, wire.code(), req.stepSeq(), "REMOVED_PENDING_RETURN",
271	                (int) (req.expectedVersion() + 1), req.occurredAt());
272	    }
273	
274	    /**
275	     * 送电类步确认在同一事务内调用：先对该间隔全部实物行加行锁，再重新检查是否仍有挂接实物。
276	     * 行锁与挂接事务的条件更新互斥，保证挂接与送电只能按合法顺序串行，不能既通过送电又留下挂接。
277	     * 不信任拟票快照，只认台账当前状态。
278	     */
279	    @Transactional
280	    public void assertNoAppliedWireOnEnergize(String intervalId) {
281	        jdbc.query("SELECT code FROM ground_wire WHERE interval_id = ? FOR UPDATE",
282	                (rs, n) -> rs.getString(1), intervalId);
283	        List<String> applied = jdbc.query(
284	                "SELECT code FROM ground_wire WHERE interval_id = ? AND status = 'APPLIED' AND occupied_by_ticket IS NOT NULL",
285	                (rs, n) -> rs.getString(1), intervalId);
286	        if (!applied.isEmpty()) {
287	            throw ApiException.unprocessable("GROUND_WIRE_STILL_APPLIED",
288	                    "实物联锁：间隔 " + intervalId + " 接地线 " + applied + " 仍挂接，禁止送电，步序不推进");
289	        }
290	    }
291	
292	    /** 归档前校验：本票借用的实物必须全部归还，历史借用记录保留不删除。 */
293	    @Transactional(readOnly = true)
294	    public void assertAllLoansReturned(long ticketId) {
295	        List<String> outstanding = jdbc.query(
296	                "SELECT wire_code FROM ground_wire_loan WHERE ticket_id = ? AND status = 'BORROWED'",
297	                (rs, n) -> rs.getString(1), ticketId);
298	        if (!outstanding.isEmpty()) {
299	            throw ApiException.unprocessable("GROUND_WIRES_NOT_RETURNED",
300	                    "本票借用接地线 " + outstanding + " 尚未全部归还，不允许归档");
301	        }
302	    }
303	
304	    /** 查询单条实物明细：台账、借用历史与不可覆盖操作证据。 */
305	    @Transactional(readOnly = true)
306	    public WireDetailView getWire(String code) {
307	        WireRow wire = mustLoadWire(code);
308	        List<LoanView> loans = jdbc.query(
309	                        "SELECT * FROM ground_wire_loan WHERE wire_code = ? ORDER BY id",
310	                        LOAN_MAPPER, code).stream()
311	                .map(GroundWireService::toLoanView)
312	                .toList();
313	        List<EvidenceView> evidences = jdbc.query(
314	                        "SELECT * FROM ground_wire_evidence WHERE wire_code = ? ORDER BY id",
315	                        EVIDENCE_MAPPER, code).stream()
316	                .map(GroundWireService::toEvidenceView)
317	                .toList();
318	        return new WireDetailView(toWireView(wire), loans, evidences);
319	    }
320	
321	    /** 查询全部实物台账，按编号排序。 */
322	    @Transactional(readOnly = true)
323	    public List<WireView> listWires() {
324	        return jdbc.query("SELECT * FROM ground_wire ORDER BY code", WIRE_MAPPER).stream()
325	                .map(GroundWireService::toWireView)
326	                .toList();
327	    }
328	
329	    /** 查询一张票关联的借用记录（含已归还历史）与全部操作证据。 */
330	    @Transactional(readOnly = true)
331	    public com.example.starter.ground.GroundWireDtos.TicketGroundView ticketGround(long ticketId) {
332	        mustLoadTicket(ticketId);
333	        List<LoanView> loans = jdbc.query(
334	                        "SELECT * FROM ground_wire_loan WHERE ticket_id = ? ORDER BY id",
335	                        LOAN_MAPPER, ticketId).stream()
336	                .map(GroundWireService::toLoanView)
337	                .toList();
338	        List<EvidenceView> evidences = jdbc.query(
339	                        "SELECT * FROM ground_wire_evidence WHERE ticket_id = ? ORDER BY id",
340	                        EVIDENCE_MAPPER, ticketId).stream()
341	                .map(GroundWireService::toEvidenceView)
342	                .toList();
343	        return new com.example.starter.ground.GroundWireDtos.TicketGroundView(ticketId, loans, evidences);
344	    }
345	
346	    private List<String> normalizedCodes(List<String> codes) {
347	        List<String> sorted = codes.stream().sorted().toList();
348	        Set<String> unique = new HashSet<>();
349	        for (String code : sorted) {
350	            if (!unique.add(code)) {
351	                throw ApiException.badRequest("DUPLICATE_WIRE_CODE", "接地线编号在同一请求中重复: " + code);
352	            }
353	        }
354	        return sorted;
355	    }
356	
357	    private void insertEvidence(String code, long ticketId, int stepSeq, String action,
358	                                String operatorId, String guardianId, Instant occurredAt,
359	                                String requestId, Instant now) {
360	        jdbc.update(
361	                "INSERT INTO ground_wire_evidence (wire_code, ticket_id, step_seq, action, operator_id, guardian_id,"
362	                        + " occurred_at, request_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
363	                code, ticketId, stepSeq, action, operatorId, guardianId,
364	                Timestamp.from(occurredAt), requestId, Timestamp.from(now));
365	    }
366	
367	    private TicketRef mustLoadTicket(long ticketId) {
368	        return jdbc.query("SELECT id, interval_id, status FROM switching_ticket WHERE id = ?",
369	                        (rs, n) -> new TicketRef(rs.getLong("id"), rs.getString("interval_id"), rs.getString("status")),
370	                        ticketId)
371	                .stream().findFirst()
372	                .orElseThrow(() -> ApiException.notFound("TICKET_NOT_FOUND", "操作票不存在: " + ticketId));
373	    }
374	
375	    private StepRef mustLoadStep(long ticketId, int seq) {
376	        return jdbc.query("SELECT seq, operation_type, status FROM switching_step WHERE ticket_id = ? AND seq = ?",
377	                        (rs, n) -> new StepRef(rs.getInt("seq"), rs.getString("operation_type"), rs.getString("status")),
378	                        ticketId, seq)
379	                .stream().findFirst()
380	                .orElseThrow(() -> ApiException.notFound("STEP_NOT_FOUND", "本票步骤不存在: " + seq));
381	    }
382	
383	    private WireRow mustLoadWire(String code) {
384	        return jdbc.query("SELECT * FROM ground_wire WHERE code = ?", WIRE_MAPPER, code)
385	                .stream().findFirst()
386	                .orElseThrow(() -> ApiException.notFound("WIRE_NOT_FOUND", "接地线不存在: " + code));
387	    }
388	
389	    private static WireView toWireView(WireRow row) {
390	        return new WireView(row.code(), row.status(), row.intervalId(), row.occupiedByTicket(),
391	                row.version(), row.updatedAt());
392	    }
393	
394	    private static LoanView toLoanView(LoanRow row) {
395	        return new LoanView(row.id(), row.ticketId(), row.intervalId(), row.wireCode(), row.status(),
396	                row.borrowedAt(), row.returnedAt(), row.returnRequestId(), row.keeperId());
397	    }
398	
399	    private static EvidenceView toEvidenceView(EvidenceRow row) {
400	        return new EvidenceView(row.id(), row.wireCode(), row.ticketId(), row.stepSeq(), row.action(),
401	                row.operatorId(), row.guardianId(), row.occurredAt(), row.requestId(), row.createdAt());
402	    }
403	
404	    /** 操作票引用。 */
405	    private record TicketRef(long id, String intervalId, String status) {
406	    }
407	
408	    /** 步骤引用。 */
409	    private record StepRef(int seq, String operationType, String status) {
410	    }
411	
412	    /** 实物台账行。 */
413	    private record WireRow(String code, String status, String intervalId, Long occupiedByTicket,
414	                          int version, Instant updatedAt) {
415	    }
416	
417	    /** 借用历史行。 */
418	    private record LoanRow(long id, String requestId, long ticketId, String intervalId, String wireCode,
419	                          String status, Instant borrowedAt, Instant returnedAt,
420	                          String returnRequestId, String keeperId) {
421	    }
422	
423	    /** 操作证据行。 */
424	    private record EvidenceRow(long id, String wireCode, long ticketId, int stepSeq, String action,
425	                              String operatorId, String guardianId, Instant occurredAt,
426	                              String requestId, Instant createdAt) {
427	    }
428	}
