499	        ExecutorService pool = Executors.newFixedThreadPool(2);
500	        CountDownLatch ready = new CountDownLatch(2);
501	        CountDownLatch start = new CountDownLatch(1);
502	        AtomicInteger attachOk = new AtomicInteger();
503	        AtomicInteger energizeOk = new AtomicInteger();
504	        AtomicInteger rejected = new AtomicInteger();
505	        Runnable attach = () -> {
506	            ready.countDown();
507	            await(start);
508	            try {
509	                // 引用本票已执行的挂线步，现场补挂实物
