530	        start.countDown();
531	        f1.get(30, TimeUnit.SECONDS);
532	        f2.get(30, TimeUnit.SECONDS);
533	        pool.shutdown();
534	
535	        assertEquals(1, attachOk.get() + energizeOk.get(), "挂接与送电只能一方成功");
536	        boolean wireApplied = "APPLIED".equals(groundService.getWire("JDX-1001").wire().status());
